do $guard$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='system_notifications' and policyname='system_notifications_owner_update') then CREATE POLICY system_notifications_owner_update ON public.system_notifications FOR UPDATE USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id)); end if; end $guard$;
