do $guard$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='x_publish_configs' and policyname='x_publish_configs_own_select') then CREATE POLICY x_publish_configs_own_select ON public.x_publish_configs FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id)); end if; end $guard$;
do $guard$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='x_publish_configs' and policyname='x_publish_configs_own_update') then CREATE POLICY x_publish_configs_own_update ON public.x_publish_configs FOR UPDATE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id)); end if; end $guard$;
do $guard$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='x_warmup_accounts' and policyname='x_warmup_accounts_owner') then CREATE POLICY x_warmup_accounts_owner ON public.x_warmup_accounts USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id)); end if; end $guard$;
do $guard$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='x_warmup_actions' and policyname='x_warmup_actions_owner') then CREATE POLICY x_warmup_actions_owner ON public.x_warmup_actions USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id)); end if; end $guard$;
